#define JOINT_VO_SUCCESSIVE_REFINEMENT_NO_MAIN
#include "joint_vo_successive_refinement.cpp"
#undef JOINT_VO_SUCCESSIVE_REFINEMENT_NO_MAIN
#include "../verifiable_ann_common.hpp"

// Fixed-design experiment: replace dense fine-centroid routing with one
// authenticated global HNSW whose stored vectors are exactly the decoded
// coarse-SQ4 + residual-PQ24 centroids.  The leaf verification protocol is
// unchanged.  The verifier replays the canonical HNSW trace using committed
// quantized codes and authenticated adjacency lists.

struct GHConfig {
    std::string data="../dataset/sift",output="global_centroid_hnsw_sift100k.csv",cache="global_centroid_hnsw_sift100k_M16.index";
    int base=100000,cal_queries=60,test_queries=500,k=100,coarse=256,fine=65536;
    int coarse_probe=54,fine_probe=863,M=16,efc=100,iters=4,pq_train=12000,pq_iters=4,repeats=1;
    std::vector<int>ef_route{863,1000,1300,1600};uint64_t seed=20260830;
};

static std::vector<int> g_ints(const std::string&s){std::vector<int>v;std::stringstream in(s);std::string x;while(std::getline(in,x,','))v.push_back(std::stoi(x));return v;}
static GHConfig g_args(int argc,char**argv){GHConfig c;for(int i=1;i<argc;++i){std::string a=argv[i];auto v=[&](){if(++i==argc)throw std::runtime_error("missing value for "+a);return std::string(argv[i]);};
    if(a=="--dataset")c.data=v();else if(a=="--output")c.output=v();else if(a=="--cache")c.cache=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--cal-queries")c.cal_queries=std::stoi(v());else if(a=="--test-queries")c.test_queries=std::stoi(v());else if(a=="--fine-probe")c.fine_probe=std::stoi(v());else if(a=="--ef-route")c.ef_route=g_ints(v());else if(a=="--M")c.M=std::stoi(v());else throw std::runtime_error("unknown option "+a);}return c;}

static vann::Matrix g_decoded_centers(const BIndex&t){vann::Matrix out;out.dimension=t.d;out.values.resize((size_t)t.counts.back()*t.d);std::vector<std::vector<float>>coarse(t.counts[0]);for(int p=0;p<t.counts[0];++p)coarse[p]=t.codec[0]->decode(t.encoded[0],p);for(int id=0;id<t.counts[1];++id){auto r=t.codec[1]->decode(t.encoded[1],id);int p=t.parent[1][id];for(int j=0;j<t.d;++j)out.values[(size_t)id*t.d+j]=coarse[p][j]+r[j];}return out;}

struct GRun {WStates states;std::vector<vann::HnswTrace>route;double records=0,expanded=0,graph_ms=0,replay_ms=0;};

static GRun g_query(const BIndex&t,const vann::HnswIndex&h,const Matrix&q,int ef,int fine_probe,int k,const std::vector<std::vector<int>>*gt){GRun out;out.states.trace.resize(q.rows());out.states.selected.assign(2,0);out.route.resize(q.rows());uint64_t hits=0;double graph_ns=0,replay_ns=0,all_ns=0;
    for(size_t qi=0;qi<q.rows();++qi){auto all_begin=std::chrono::steady_clock::now(),begin=all_begin;auto trace=vann::search_hnsw(h,q[qi],ef,fine_probe);graph_ns+=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count();begin=std::chrono::steady_clock::now();vann::verify_hnsw_route(h,q[qi],ef,fine_probe,trace);replay_ns+=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count();
        auto&dst=out.states.trace[qi];dst.selected.resize(2);dst.selected[1]=trace.answer;std::vector<uint8_t>seen_parent(t.counts[0]);for(int f:trace.answer){int p=t.parent[1][f];if(!seen_parent[p]){seen_parent[p]=1;dst.selected[0].push_back(p);}dst.leaf.lists.push_back(f);}std::priority_queue<std::pair<float,int>>top;for(int f:dst.leaf.lists)for(int id:t.lists[f]){float d=l2(q[qi],(*t.xb)[id],t.d);if((int)top.size()<k)top.push({d,id});else if(d<top.top().first||(d==top.top().first&&id<top.top().second)){top.pop();top.push({d,id});}out.states.visited++;}
        if((int)top.size()!=k)throw std::runtime_error("centroid graph returned fewer than k objects");dst.leaf.tau2=top.top().first;while(!top.empty()){dst.leaf.answer.push_back(top.top().second);top.pop();}if(gt){std::unordered_set<int>a(dst.leaf.answer.begin(),dst.leaf.answer.end());for(int id:(*gt)[qi])hits+=a.count(id);}out.records+=trace.disclosed.size();out.expanded+=trace.opened.size();out.states.selected[0]+=dst.selected[0].size();out.states.selected[1]+=dst.selected[1].size();out.route[qi]=std::move(trace);all_ns+=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-all_begin).count();}
    double nq=q.rows();out.records/=nq;out.expanded/=nq;out.graph_ms=graph_ns/nq/1e6;out.replay_ms=replay_ns/nq/1e6;out.states.visited/=nq;for(double&x:out.states.selected)x/=nq;out.states.recall=gt?hits/(nq*k):0;out.states.routing_ms=out.graph_ms;out.states.query_ms=all_ns/nq/1e6;return out;}

struct GRoute {double parameters=0,coarse_codes=0,node_metadata=0,residual_codes=0,adjacency=0,unopened_hashes=0,node_proofs=0,fine_metadata=0,fine_proofs=0,total=0;};

static bool g_open(const vann::HnswTrace&t,int id,int level){return std::binary_search(t.opened.begin(),t.opened.end(),vann::OpenedAdjacency{id,level},[](const auto&a,const auto&b){return a.local_id<b.local_id||(a.local_id==b.local_id&&a.level<b.level);});}

static GRoute g_route(const BIndex&t,const vann::HnswIndex&h,const GRun&run,int M,int efc){GRoute out;out.parameters=96.0+t.codec[0]->parameter_bytes()+t.codec[1]->parameter_bytes()+t.codec[0]->huffman_model_bytes();std::vector<int>coarse(t.counts[0]);std::iota(coarse.begin(),coarse.end(),0);out.coarse_codes=t.codec[0]->huffman_bytes(coarse);for(const auto&trace:run.route){out.node_proofs+=hv_dummy_proof_count(t.counts[1],trace.disclosed)*32.0;out.fine_metadata+=trace.answer.size()*4.0;out.fine_proofs+=hv_dummy_proof_count(t.counts[1],trace.answer)*32.0;for(int id:trace.disclosed){out.node_metadata+=12.0;out.residual_codes+=t.codec[1]->code_bytes();int levels=h.index->hnsw.levels.at((size_t)id);for(int level=0;level<levels;++level){out.adjacency+=5.0;if(g_open(trace,id,level))out.adjacency+=h.neighbors(id,level).size()*4.0;else out.unopened_hashes+=32.0;}}}
    double nq=run.route.size();out.node_metadata/=nq;out.residual_codes/=nq;out.adjacency/=nq;out.unopened_hashes/=nq;out.node_proofs/=nq;out.fine_metadata/=nq;out.fine_proofs/=nq;out.total=out.parameters+out.coarse_codes+out.node_metadata+out.residual_codes+out.adjacency+out.unopened_hashes+out.node_proofs+out.fine_metadata+out.fine_proofs+16.0+(M>0&&efc>0?0.0:0.0);return out;}


static std::vector<int> g_bfs_positions(const vann::HnswIndex&h){int n=h.size();std::vector<int>order,pos(n,-1);order.reserve(n);std::vector<uint8_t>seen(n);std::queue<int>q;auto component=[&](int start){seen[start]=1;q.push(start);while(!q.empty()){int u=q.front();q.pop();order.push_back(u);for(int v:h.neighbors(u,0))if(!seen[v]){seen[v]=1;q.push(v);}}};int entry=h.index->hnsw.entry_point;if(entry>=0)component(entry);for(int id=0;id<n;++id)if(!seen[id])component(id);for(int z=0;z<n;++z)pos[order[z]]=z;return pos;}

// Vertical commitments: one code-record tree and one adjacency-record tree.
// Code records may be disclosed in small BFS-contiguous blocks. Only nodes
// whose adjacency is expanded are opened in the adjacency tree.
static GRoute g_route_split(const BIndex&t,const vann::HnswIndex&h,const GRun&run,const std::vector<int>&pos,int block){GRoute out;out.parameters=96.0+t.codec[0]->parameter_bytes()+t.codec[1]->parameter_bytes()+t.codec[0]->huffman_model_bytes();std::vector<int>coarse(t.counts[0]);std::iota(coarse.begin(),coarse.end(),0);out.coarse_codes=t.codec[0]->huffman_bytes(coarse);int n=t.counts[1],nb=(n+block-1)/block;
    for(const auto&trace:run.route){std::vector<int>blocks;blocks.reserve(trace.disclosed.size());for(int id:trace.disclosed)blocks.push_back(pos[id]/block);std::sort(blocks.begin(),blocks.end());blocks.erase(std::unique(blocks.begin(),blocks.end()),blocks.end());int opened_records=0;for(int b:blocks)opened_records+=std::min(block,n-b*block);out.node_metadata+=opened_records*12.0;out.residual_codes+=opened_records*t.codec[1]->code_bytes();out.node_proofs+=hv_dummy_proof_count(nb,blocks)*32.0;
        std::vector<int>expanded;expanded.reserve(trace.opened.size());for(const auto&o:trace.opened)expanded.push_back(o.local_id);std::sort(expanded.begin(),expanded.end());expanded.erase(std::unique(expanded.begin(),expanded.end()),expanded.end());std::vector<int>mapped;for(int id:expanded)mapped.push_back(pos[id]);out.node_proofs+=hv_dummy_proof_count(n,mapped)*32.0;
        for(int id:expanded){int levels=h.index->hnsw.levels.at((size_t)id),opened_levels=0;out.adjacency+=8.0;for(int level=0;level<levels;++level)if(g_open(trace,id,level)){++opened_levels;out.adjacency+=5.0+h.neighbors(id,level).size()*4.0;}out.unopened_hashes+=(levels-opened_levels)*32.0;}
        out.fine_metadata+=trace.answer.size()*4.0;mapped.clear();for(int id:trace.answer)mapped.push_back(pos[id]);out.fine_proofs+=hv_dummy_proof_count(n,mapped)*32.0;}
    double nq=run.route.size();out.node_metadata/=nq;out.residual_codes/=nq;out.adjacency/=nq;out.unopened_hashes/=nq;out.node_proofs/=nq;out.fine_metadata/=nq;out.fine_proofs/=nq;out.total=out.parameters+out.coarse_codes+out.node_metadata+out.residual_codes+out.adjacency+out.unopened_hashes+out.node_proofs+out.fine_metadata+out.fine_proofs+16.0;return out;}

int main(int argc,char**argv)try{auto c=g_args(argc,argv);Matrix xb=fvecs(c.data+"/sift_base.fvecs",c.base),calq=fvecs(c.data+"/sift_learn.fvecs",c.cal_queries),testq=fvecs(c.data+"/sift_query.fvecs",c.test_queries);auto calgt=exact_gt(xb,calq,c.k),testgt=exact_gt(xb,testq,c.k);std::cerr<<"Build shared residual index...\n";auto lists=hkmeans(xb,c.fine,c.iters);Matrix fine=cr_matrix(centers(xb,lists));BCfg bc;bc.base=c.base;bc.counts={c.coarse,c.fine};bc.modes={"sq4","pq24"};bc.iters=c.iters;bc.pq_train=c.pq_train;bc.pq_iters=c.pq_iters;bc.seed=c.seed;auto tree=b_build(xb,bc,&lists,&fine);
    auto dense_train=w_query(tree,calq,{c.coarse_probe,c.fine_probe},c.k,&calgt),dense_test=w_query(tree,testq,{c.coarse_probe,c.fine_probe},c.k,&testgt);auto dense=w_full(tree,calq,dense_train,testq,dense_test,c.repeats);std::cerr<<"Build/load global centroid HNSW...\n";auto decoded=g_decoded_centers(tree);auto graph=vann::build_hnsw(decoded,c.M,c.efc,c.cache);
    auto bfs=g_bfs_positions(graph);std::ofstream out(c.output);out<<std::setprecision(12)<<"protocol,block_size,ef_route,recall,avg_route_records,avg_expanded,avg_leaf_objects,avg_leaf_refined,avg_leaf_exact,leaf_base_kib,leaf_refine_kib,leaf_exact_kib,leaf_refinement_merkle_kib,leaf_exact_merkle_kib,route_parameters_kib,route_coarse_codes_kib,route_node_metadata_kib,route_residual_codes_kib,route_adjacency_kib,route_unopened_hashes_kib,route_node_proofs_kib,route_fine_metadata_kib,route_fine_proofs_kib,route_total_kib,leaf_kib,total_kib,dense_recall,dense_route_kib,dense_leaf_kib,dense_total_kib,vo_reduction,server_query_ms,graph_ms,client_replay_ms,vo_generation_ms,selection_mismatches,object_violations\n";
    for(int ef:c.ef_route){if(ef<c.fine_probe)continue;std::cerr<<"efRoute="<<ef<<"...\n";auto train=g_query(tree,graph,calq,ef,c.fine_probe,c.k,&calgt),test=g_query(tree,graph,testq,ef,c.fine_probe,c.k,&testgt);auto leaf=w_full(tree,calq,train.states,testq,test.states,c.repeats);auto internal=w_route(tree,test.states);double leaf_params=leaf.route*1024.0-std::min(internal.fixed,internal.huffman);
        auto emit=[&](const std::string&name,int block,GRoute route){route.total+=leaf_params;double route_kib=route.total/1024.0,total=route_kib+leaf.leaf;out<<name<<','<<block<<','<<ef<<','<<test.states.recall<<','<<test.records<<','<<test.expanded<<','<<test.states.visited<<","<<leaf.refined<<","<<leaf.exact<<","<<leaf.base_payload<<","<<leaf.refine_payload<<","<<leaf.exact_payload<<","<<leaf.refinement_merkle<<","<<leaf.exact_merkle<<','<<route.parameters/1024.0<<','<<route.coarse_codes/1024.0<<','<<route.node_metadata/1024.0<<','<<route.residual_codes/1024.0<<','<<route.adjacency/1024.0<<','<<route.unopened_hashes/1024.0<<','<<route.node_proofs/1024.0<<','<<route.fine_metadata/1024.0<<','<<route.fine_proofs/1024.0<<','<<route_kib<<','<<leaf.leaf<<','<<total<<','<<dense_test.recall<<','<<dense.route<<','<<dense.leaf<<','<<dense.total<<','<<1.0-total/dense.total<<','<<test.states.query_ms<<','<<test.graph_ms<<','<<test.replay_ms<<','<<leaf.vo_ms<<','<<0<<','<<leaf.violations<<'\n';std::cout<<name<<" block="<<block<<" efRoute="<<ef<<" recall="<<test.states.recall<<" records="<<test.records<<" route="<<route_kib<<" KiB leaf="<<leaf.leaf<<" KiB total="<<total<<" KiB reduction="<<(1-total/dense.total)*100<<"%\n";};
        emit("monolithic_identity",1,g_route(tree,graph,test,c.M,c.efc));for(int block:{1,4,8,16,32})emit("split_bfs",block,g_route_split(tree,graph,test,bfs,block));}
    std::cout<<"dense recall="<<dense_test.recall<<" route="<<dense.route<<" leaf="<<dense.leaf<<" total="<<dense.total<<" KiB\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
